describe('Search Field Dropdown Matching Options', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-field"]').as('searchField');
    cy.get('[data-testid="dropdown-options"]').as('dropdown');
  });

  it('should display matching dropdown options when typing in search field', () => {
    cy.get('@searchField').type('apple');

    cy.get('@dropdown').should('be.visible');
    cy.get('@dropdown').find('[data-testid="option-item"]').should('have.length.greaterThan', 0);

    cy.get('@dropdown').find('[data-testid="option-item"]').each(($option) => {
      cy.wrap($option).should('contain.text', /apple/i);
    });
  });

  it('should filter options based on search input and update dynamically', () => {
    cy.get('@searchField').type('ban');

    cy.get('@dropdown').find('[data-testid="option-item"]').should('have.length.greaterThan', 0);
    cy.get('@dropdown').find('[data-testid="option-item"]').first().should('contain.text', /ban/i);

    cy.get('@searchField').clear().type('banana');

    cy.get('@dropdown').find('[data-testid="option-item"]').should('have.length.greaterThan', 0);
    cy.get('@dropdown').find('[data-testid="option-item"]').first().should('contain.text', /banana/i);
  });

  it('should hide dropdown when search field is empty', () => {
    cy.get('@searchField').type('test');
    cy.get('@dropdown').should('be.visible');

    cy.get('@searchField').clear();
    cy.get('@dropdown').should('not.be.visible');
  });

  it('should handle no matching results gracefully', () => {
    cy.get('@searchField').type('xyznonexistent');

    cy.get('@dropdown').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('be.visible').and('contain.text', 'No matching options');
    cy.get('@dropdown').find('[data-testid="option-item"]').should('have.length', 0);
  });

  it('should select option from dropdown and populate search field', () => {
    cy.get('@searchField').type('orange');

    cy.get('@dropdown').find('[data-testid="option-item"]').first().click();

    cy.get('@searchField').should('have.value', 'orange');
    cy.get('@dropdown').should('not.be.visible');
  });

  it('should handle special characters and case-insensitive matching', () => {
    cy.get('@searchField').type('APPLE');

    cy.get('@dropdown').should('be.visible');
    cy.get('@dropdown').find('[data-testid="option-item"]').should('have.length.greaterThan', 0);
    cy.get('@dropdown').find('[data-testid="option-item"]').first().should('contain.text', /apple/i);
  });

  it('should close dropdown when clicking outside search field', () => {
    cy.get('@searchField').type('test');
    cy.get('@dropdown').should('be.visible');

    cy.get('body').click(0, 0);
    cy.get('@dropdown').should('not.be.visible');
  });

  it('should navigate dropdown options using keyboard arrows', () => {
    cy.get('@searchField').type('app');
    cy.get('@dropdown').should('be.visible');

    cy.get('@searchField').type('{downarrow}');
    cy.get('@dropdown').find('[data-testid="option-item"]').first().should('have.class', 'highlighted');

    cy.get('@searchField').type('{downarrow}');
    cy.get('@dropdown').find('[data-testid="option-item"]').eq(1).should('have.class', 'highlighted');

    cy.get('@searchField').type('{uparrow}');
    cy.get('@dropdown').find('[data-testid="option-item"]').first().should('have.class', 'highlighted');
  });
});
